-- READ-ONLY relational integrity checks, one row per (source, check). No writes.
-- fail = rows violating the check; scope = rows examined.
select * from (
-- 1. Price row's style must equal the variant's own model (no cross-model price)
select 'ss' src,'price_style_matches_variant' chk, count(*) filter (where c.style_code<>v.style_code) fail, count(*) scope from catalog_variant_prices c join ss_variants v on v.sku=c.sku where c.source='ss'
union all select 'mf','price_style_matches_variant', count(*) filter (where c.style_code<>v.style_code), count(*) from catalog_variant_prices c join mf_variants v on v.sku=c.sku where c.source='mf'
union all select 'bb','price_style_matches_variant', count(*) filter (where c.style_code<>v.style_code), count(*) from catalog_variant_prices c join bb_variants v on v.sku=c.sku where c.source='bb'
union all select 'pf','price_style_matches_variant', count(*) filter (where c.style_code<>v.model_code), count(*) from catalog_variant_prices c join pf_variants v on v.item_code=c.sku where c.source='pf'
union all select 'utt','price_style_matches_variant', count(*) filter (where c.style_code<>v.style_code), count(*) from catalog_variant_prices c join utt_variants v on v.sku=c.sku where c.source='utt'
union all select 'fr','price_style_matches_variant', count(*) filter (where c.style_code<>v.style_code), count(*) from catalog_variant_prices c join falkross_variants v on v.sku=c.sku where c.source='fr'
union all select 'nwg','price_style_matches_variant', count(*) filter (where c.style_code<>k.product_number), count(*) from catalog_variant_prices c join nwg_skus k on k.sku=c.sku where c.source='nwg'
-- 2. Price row colour/size equal the variant's own colour/size (what the size table shows)
union all select 'ss','price_color_size_match_variant', count(*) filter (where c.color_code is distinct from v.color_code or c.size is distinct from v.size_code), count(*) from catalog_variant_prices c join ss_variants v on v.sku=c.sku where c.source='ss'
union all select 'mf','price_color_size_match_variant', count(*) filter (where c.color_code is distinct from v.color_code or c.size is distinct from coalesce(v.size_name,v.size)), count(*) from catalog_variant_prices c join mf_variants v on v.sku=c.sku where c.source='mf'
union all select 'bb','price_color_size_match_variant', count(*) filter (where c.color_code is distinct from v.color_name or c.size is distinct from v.size), count(*) from catalog_variant_prices c join bb_variants v on v.sku=c.sku where c.source='bb'
union all select 'utt','price_color_size_match_variant', count(*) filter (where c.color_code is distinct from v.color_name or c.size is distinct from v.size), count(*) from catalog_variant_prices c join utt_variants v on v.sku=c.sku where c.source='utt'
union all select 'fr','price_color_size_match_variant', count(*) filter (where c.color_code is distinct from v.color_name or c.size is distinct from v.size), count(*) from catalog_variant_prices c join falkross_variants v on v.sku=c.sku where c.source='fr'
union all select 'nwg','price_color_size_match_variant', count(*) filter (where c.color_code is distinct from v.color_code or c.size is distinct from coalesce(nullif(k.size_name,''),k.size)), count(*) from catalog_variant_prices c join nwg_skus k on k.sku=c.sku join nwg_variants v on v.item_number=k.item_number where c.source='nwg'
-- 3. SKU code prefix belongs to its model (code-family ownership)
union all select 'nwg','sku_prefix_owned_by_model', count(*) filter (where left(sku,length(product_number)+1)<>product_number||'-'), count(*) from nwg_skus
union all select 'pf','item_prefix_owned_by_model', count(*) filter (where left(item_code,length(model_code))<>model_code), count(*) from pf_variants
union all select 'mf','sku_prefix_owned_by_model', count(*) filter (where left(sku,length(style_code))<>style_code), count(*) from mf_variants
union all select 'ss','sku_prefix_owned_by_model', count(*) filter (where left(sku,length(style_code))<>style_code), count(*) from ss_variants
-- 4. Same SKU listed under two models
union all select 'all','sku_in_multiple_styles', count(*), (select count(*) from catalog_variant_prices) from (select source,sku from catalog_variant_prices group by 1,2 having count(distinct style_code)>1) x
-- 5. Duplicate colour+size within one model (ambiguous size table)
union all select 'ss','dup_color_size_in_model', count(*), (select count(*) from ss_variants where published) from (select style_code,color_code,size_code from ss_variants where published group by 1,2,3 having count(*)>1) x
union all select 'mf','dup_color_size_in_model', count(*), (select count(*) from mf_variants) from (select style_code,color_code,size_name from mf_variants group by 1,2,3 having count(*)>1) x
union all select 'bb','dup_color_size_in_model', count(*), (select count(*) from bb_variants where active) from (select style_code,color_name,size from bb_variants where active group by 1,2,3 having count(*)>1) x
union all select 'utt','dup_color_size_in_model', count(*), (select count(*) from utt_variants where active) from (select style_code,color_name,size from utt_variants where active group by 1,2,3 having count(*)>1) x
union all select 'fr','dup_color_size_in_model', count(*), (select count(*) from falkross_variants where active) from (select style_code,color_name,size from falkross_variants where active group by 1,2,3 having count(*)>1) x
union all select 'pf','dup_color_size_in_model', count(*), (select count(*) from pf_variants where feed_active) from (select model_code,coalesce(color_key,color_code),size from pf_variants where feed_active group by 1,2,3 having count(*)>1) x
union all select 'nwg','dup_color_size_in_model', count(*), (select count(*) from nwg_skus where coalesce(active,true)) from (select item_number,coalesce(nullif(size_name,''),size) from nwg_skus where coalesce(active,true) and not coalesce(discontinued,false) group by 1,2 having count(*)>1) x
-- 6. Colour-tagged images whose colour no variant of that model has (gallery cannot select / wrong owner)
union all select 'ss','image_color_not_in_model', count(*) filter (where not exists (select 1 from ss_variants v where v.style_code=i.style_code and v.color_code=i.color_code)), count(*) from ss_images i
union all select 'mf','image_color_not_in_model', count(*) filter (where i.color_code is not null and not exists (select 1 from mf_variants v where v.style_code=i.style_code and v.color_code=i.color_code)), count(*) from mf_images i
union all select 'bb','image_color_not_in_model', count(*) filter (where i.color_name is not null and not exists (select 1 from bb_variants v where v.style_code=i.style_code and lower(v.color_name)=lower(i.color_name))), count(*) from bb_images i
union all select 'utt','image_color_not_in_model', count(*) filter (where i.color_name is not null and not exists (select 1 from utt_variants v where v.style_code=i.style_code and v.color_name=i.color_name)), count(*) from utt_images i
union all select 'fr','image_color_not_in_model', count(*) filter (where i.color_name is not null and not exists (select 1 from falkross_variants v where v.style_code=i.style_code and v.color_name=i.color_name)), count(*) from falkross_images i
union all select 'pf','image_item_not_in_model', count(*) filter (where not exists (select 1 from pf_variants v where v.item_code=i.item_code and v.model_code=i.model_code)), count(*) from pf_images i
union all select 'nwg','image_variant_not_in_model', count(*) filter (where i.item_number is not null and not exists (select 1 from nwg_variants v where v.item_number=i.item_number and v.product_number=i.product_number)), count(*) from nwg_images i
union all select 'ru','image_color_not_in_model', count(*) filter (where i.color_name is not null and not exists (select 1 from ru_variants v where v.style_code=i.style_code and v.color_name=i.color_name)), count(*) from ru_images i
-- 7. Visible colours with no own photo (honest missing state candidates)
union all select 'bb','visible_color_without_own_image', count(*) filter (where not exists (select 1 from bb_images i where i.style_code=c.style_code and lower(i.color_name)=lower(c.color_name))), count(*) from (select distinct v.style_code,v.color_name from bb_variants v join bb_styles s using(style_code) where v.active and s.active) c
union all select 'ss','visible_color_without_own_image', count(*) filter (where not exists (select 1 from ss_images i where i.style_code=c.style_code and i.color_code=c.color_code)), count(*) from (select distinct v.style_code,v.color_code from ss_variants v join ss_styles s using(style_code) where v.published and s.published and not coalesce(s.archived,false)) c
union all select 'mf','visible_color_without_own_image', count(*) filter (where not exists (select 1 from mf_images i where i.style_code=c.style_code and i.color_code=c.color_code)), count(*) from (select distinct v.style_code,v.color_code from mf_variants v join mf_styles s using(style_code) where s.published and not s.hidden_by_admin and not s.is_outlet) c
union all select 'utt','visible_color_without_own_image', count(*) filter (where not exists (select 1 from utt_images i where i.style_code=c.style_code and i.color_name=c.color_name and i.url is not null)), count(*) from (select distinct v.style_code,v.color_name from utt_variants v join utt_styles s using(style_code) where v.active and s.published and not s.hidden_by_admin and not v.outlet) c
union all select 'fr','visible_color_without_own_image', count(*) filter (where not exists (select 1 from falkross_images i where i.style_code=c.style_code and i.color_name=c.color_name and i.url is not null)), count(*) from (select distinct v.style_code,v.color_name from falkross_variants v join falkross_styles s using(style_code) where v.active and s.published and not s.hidden_by_admin) c
union all select 'nwg','visible_color_without_own_image', count(*) filter (where not exists (select 1 from nwg_images i where i.item_number=c.item_number)), count(*) from (select distinct v.item_number from nwg_variants v join nwg_styles s using(product_number) where s.brand in ('Craft','Clique','ProJob','Cutter & Buck') and coalesce(s.published,true) and not coalesce(s.archived,false)) c
) t order by 1,2;
